// Agoda — 3Sum (LeetCode 15), then 3Sum Closest (LeetCode 16). Sort + two pointers, O(n^2).
public static class ThreeSum {
    // Unique triplets summing to zero, each ascending, listed in ascending order.
    public static List<(int A, int B, int C)> ZeroTriplets(int[] nums) {
        var res = new List<(int, int, int)>();
        if (nums == null || nums.Length < 3) return res;
        var a = (int[])nums.Clone(); Array.Sort(a);
        for (int i = 0; i < a.Length - 2; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue;              // skip duplicate anchors
            int l = i + 1, r = a.Length - 1;
            while (l < r) {
                long s = (long)a[i] + a[l] + a[r];
                if (s < 0) l++;
                else if (s > 0) r--;
                else {
                    res.Add((a[i], a[l], a[r]));
                    while (l < r && a[l] == a[l + 1]) l++;
                    while (l < r && a[r] == a[r - 1]) r--;
                    l++; r--;
                }
            }
        }
        return res;
    }

    // The sum of three elements closest to target (ties: the smaller sum).
    public static long Closest(int[] nums, int target) {
        if (nums == null || nums.Length < 3) throw new ArgumentException("need at least three numbers");
        var a = (int[])nums.Clone(); Array.Sort(a);
        long best = (long)a[0] + a[1] + a[2];
        for (int i = 0; i < a.Length - 2; i++) {
            int l = i + 1, r = a.Length - 1;
            while (l < r) {
                long s = (long)a[i] + a[l] + a[r];
                long d = Math.Abs(s - target), bd = Math.Abs(best - target);
                if (d < bd || (d == bd && s < best)) best = s;
                if (s == target) return s;
                if (s < target) l++; else r--;
            }
        }
        return best;
    }
}
